// Browser Revision 4 advisor (apps/web/src/features/advisor/model.mjs) against the Python
// reference (tools/economy/advisor_eco/advisor_model_rev4.py, default weights) for all 3,080
// plans. Expectations: tests/advisor/fixtures/rev4-plans.json.gz, regenerated by
// python tools/economy/advisor_eco/build_advisor_parity_fixture.py.
// Data: the committed advisor DB + data/golden/advisor_cell_metrics.json.gz, shaped exactly like
// the published /api/advisor-matchups/<civ> rows (checked against the fixture's row digest).
import test from 'node:test';
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import {readFileSync} from 'node:fs';
import {gunzipSync} from 'node:zlib';
import {DatabaseSync} from 'node:sqlite';
import {buildAdvisorRecommendations, invertMatchup, pyRound, CONFIG, WEIGHTS} from '../../apps/web/src/features/advisor/model.mjs';

const root = new URL('../../', import.meta.url);
const read = path => readFileSync(new URL(path, root));
const fixture = JSON.parse(gunzipSync(read('tests/advisor/fixtures/rev4-plans.json.gz')));
const metricsBytes = read('data/golden/advisor_cell_metrics.json.gz');
const metrics = JSON.parse(gunzipSync(metricsBytes));
const sha = bytes => createHash('sha256').update(bytes).digest('hex');

const db = new DatabaseSync(new URL('data/golden/civ_matchups_first_pass.db', root).pathname, {readOnly: true});
const units = new Map(db.prepare('SELECT data FROM units ORDER BY id').all().map(row => {
    const unit = JSON.parse(row.data);
    return [unit.id, {...unit, full_research_vm: metrics.fullResearchVm[String(unit.id)] ?? null}];
}));
const cells = db.prepare('SELECT * FROM cells ORDER BY a, b').all();
db.close();
const byCell = new Map(metrics.cells.map(row => [`${row[0]}:${row[1]}`, row]));

/** Same as cell_fields() in apps/backend/aoe2_api/services/advisor.py. */
function ecoFields(a, b, outcome, evidence, swapped) {
    const found = byCell.get(swapped ? `${b}:${a}` : `${a}:${b}`);
    const vm = !found ? [null, null] : swapped ? [found[6], found[5]] : [found[5], found[6]];
    if (['equivalent', 'close_uncertain'].includes(outcome) || evidence === 'identity') return ['close', 'close', null, ...vm];
    if (evidence === 'inferred') return ['pending', 'pending', null, null, null];
    if (!found || found[2] === 'close') throw new Error(`stale metrics for ${a}/${b}`);
    return [...(swapped ? [found[3], found[2]] : [found[2], found[3]]), found[4], ...vm];
}

/** Rows of /api/advisor-matchups/<left> for opponent <right>, in the API's order (cells ORDER BY a, b). */
const pairRows = new Map();
for (const cell of cells) {
    const civA = units.get(cell.a).civilization, civB = units.get(cell.b).civilization;
    if (civA === civB) continue;
    for (const [own, swapped] of [[civA, false], [civB, true]]) {
        const base = [cell.a, cell.b, cell.outcome, cell.evidence_type, cell.count_a, cell.count_b, cell.tier, cell.flags, cell.evidence_id];
        const row = swapped ? invertMatchup(base) : base;
        const key = `${own}|${swapped ? civA : civB}`;
        if (!pairRows.has(key)) pairRows.set(key, []);
        pairRows.get(key).push([...row, ...ecoFields(row[0], row[1], row[2], row[3], swapped)]);
    }
}

const round = x => x === null ? null : pyRound(x, fixture.header.digits);
const ids = list => list.map(e => e.unit.id);
function summary(p) {
    const sup = p.support;
    return {
        main: p.main.unit.id, mainAdvantage: round(p.main.adv), mainBase: round(p.main.base),
        targets: p.targets, support: sup ? sup.entry.unit.id : null, supportScore: sup ? round(sup.score) : null,
        helps: sup ? sup.helps.map(h => [h.opp, h.kind, h.why, round(h.value)]) : [],
        additions: p.additions.map(a => [a.entry.unit.id, a.covers]),
        uncovered: p.uncovered, unanswered: p.unanswered, alternatives: ids(p.alternatives),
        strength: Object.fromEntries([...p.strength].sort((a, b) => a[0] - b[0]).map(([k, v]) => [String(k), round(v)])),
    };
}

test('the fixture was generated from the committed data and the same settings', () => {
    assert.equal(fixture.header.cellMetricsSha256, sha(metricsBytes),
        'stale fixture: run python tools/economy/advisor_eco/build_advisor_parity_fixture.py');
    assert.equal(fixture.header.advisorDatasetSha256, metrics.advisorDataset.sha256);
    assert.equal(fixture.header.plans, 3080);
    assert.equal(fixture.plans.length, 3080);
    assert.equal(fixture.header.referenceDifferences, 0, 'Python plans differ from docs/army-economics/advisor-plans-rev4.json.gz');
    assert.deepEqual(fixture.header.weightValues, {...WEIGHTS});
    const c = fixture.header.config;
    assert.deepEqual([c.strength, c.lo, c.hi, c.gold_main, c.struggle_hp, c.struggle_power, c.struggle_power_hp, c.struggle_close,
        c.help_hp_margin, c.help_eco, c.help_tie_bonus, c.excluded_main, c.support_extra],
    [CONFIG.strength, CONFIG.lo, CONFIG.hi, CONFIG.goldMain, CONFIG.struggleHp, CONFIG.strugglePower, CONFIG.strugglePowerHp,
        CONFIG.struggleClose, CONFIG.helpHpMargin, CONFIG.helpEco, CONFIG.helpTieBonus, [...CONFIG.excludedMain], [...CONFIG.supportExtra]]);
});

test('rows assembled here are the rows the API serves', () => {
    // Same text as row_digest() in build_advisor_parity_fixture.py.
    const hash = createHash('sha256');
    for (const key of [...pairRows.keys()].sort()) hash.update(`${key}\n${JSON.stringify(pairRows.get(key))}\n`);
    assert.equal(hash.digest('hex'), fixture.header.rowsSha256);
});

test('every one of the 3,080 plans equals the Python reference exactly', () => {
    const expected = new Map(fixture.plans.map(p => [`${p.civ}|${p.enemy}`, p]));
    const failures = [];
    const civs = [...new Set([...units.values()].map(u => u.civilization))].sort();
    let compared = 0;
    for (let i = 0; i < civs.length; i += 1) {
        for (let j = i + 1; j < civs.length; j += 1) {
            const plans = buildAdvisorRecommendations(pairRows.get(`${civs[i]}|${civs[j]}`), units);
            for (const [side, civ, enemy] of [['left', civs[i], civs[j]], ['right', civs[j], civs[i]]]) {
                const {civ: _c, enemy: _e, ...want} = expected.get(`${civ}|${enemy}`);
                try { assert.deepEqual(summary(plans[side]), want); } catch (error) { failures.push(`${civ} vs ${enemy}: ${error.message.slice(0, 400)}`); }
                compared += 1;
            }
        }
    }
    assert.equal(compared, 3080);
    assert.deepEqual(failures.slice(0, 5), [], `${failures.length} plans differ`);
});
